#!/usr/bin/env node
// Bundles the files the app used to read off disk at request time into one generated module,
// src/generated/kun-bundle.ts (git-ignored; regenerated by postinstall, predev and prebuild).
//
// Why: on Cloudflare Workers there is no filesystem, so these cannot be fs reads at request
// time. Everything here is static content that already lives in the repo:
//   - web/install.sh, web/install.ps1   -> the /install and /install.ps1 routes (byte-identical)
//   - content/docs/**/*.mdx             -> the Second Brain graph's notes layer (slug/title/links)
//   - content/carousels/<brand>/*.json  -> kun-owned carousel decks (raw JSON, validated at read)
//   - public/carousel-art/*             -> which vendored art files exist (else the CDN is used)
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const read = (...p) => fs.readFileSync(path.join(root, ...p), "utf8");
const list = (dir) => (fs.existsSync(dir) ? fs.readdirSync(dir, { withFileTypes: true }) : []);

// ── Graph notes: same extraction the graph used to do at runtime ──────────────
function collectNotes() {
  const docs = path.join(root, "content/docs");
  const files = [];
  const walk = (dir) => {
    for (const e of list(dir)) {
      const full = path.join(dir, e.name);
      if (e.isDirectory()) walk(full);
      else if (e.name.endsWith(".mdx")) files.push(full);
    }
  };
  walk(docs);
  files.sort();
  return files.map((file) => {
    const raw = fs.readFileSync(file, "utf8");
    const slug = path.relative(docs, file).replace(/\.mdx$/, "").split(path.sep).join("/");
    const fm = raw.match(/^---\n([\s\S]*?)\n---/)?.[1] ?? "";
    const field = (name) =>
      fm.match(new RegExp(`^${name}:\\s*(.+)$`, "m"))?.[1].trim().replace(/^["']|["']$/g, "") ?? "";
    const links = [...raw.matchAll(/\]\((?:\/(?:en|ar))?\/docs\/([a-zA-Z0-9/_-]+)/g)].map((m) => m[1].replace(/\/$/, ""));
    return {
      slug,
      title: field("title") || slug,
      description: field("description"),
      links: [...new Set(links)].filter((l) => l !== slug),
    };
  });
}

// ── Kun-owned carousel decks ──────────────────────────────────────────────────
const decks = {};
for (const brand of list(path.join(root, "content/carousels"))) {
  if (!brand.isDirectory()) continue;
  for (const f of list(path.join(root, "content/carousels", brand.name))) {
    if (f.name.endsWith(".json")) {
      decks[`${brand.name}/${f.name.replace(/\.json$/, "")}`] = read("content/carousels", brand.name, f.name);
    }
  }
}

const art = list(path.join(root, "public/carousel-art")).filter((e) => e.isFile()).map((e) => e.name).sort();

const out = `// GENERATED by scripts/gen-bundle.mjs — do not edit, do not commit.
export const INSTALL_SH: string = ${JSON.stringify(read("web/install.sh"))};
export const INSTALL_PS1: string = ${JSON.stringify(read("web/install.ps1"))};
export const GRAPH_NOTES: { slug: string; title: string; description: string; links: string[] }[] = ${JSON.stringify(collectNotes())};
export const CAROUSEL_DECKS: Record<string, string> = ${JSON.stringify(decks)};
export const CAROUSEL_ART: string[] = ${JSON.stringify(art)};
`;
const dest = path.join(root, "src/generated/kun-bundle.ts");
fs.mkdirSync(path.dirname(dest), { recursive: true });
fs.writeFileSync(dest, out);
console.log(`gen-bundle: ${Object.keys(decks).length} deck(s), ${art.length} art file(s), ${out.length} bytes -> src/generated/kun-bundle.ts`);
